/* SolidCutlist service worker — generated by build-pwa.js, do not edit dist-pwa/sw.js.
 *
 * Offline strategy: every file of the app is downloaded into a versioned cache when the
 * worker installs, and then always served from that cache (so the app opens with no
 * signal). A new deploy produces a new version; the page shows "Update available" and
 * switches only when the user taps it, so nobody loses work mid-edit.
 */
const VERSION = 'c82eb5e95b28';
const CACHE = 'solidcutlist-' + VERSION;
const PRECACHE = [
    "./",
    "./icons/apple-touch-icon.png",
    "./icons/favicon-32.png",
    "./icons/icon-maskable-192.png",
    "./icons/icon-maskable-512.png",
    "./icons/logo-192.png",
    "./icons/logo-512.png",
    "./index.html",
    "./manifest.webmanifest",
    "./starter-packs/starter_EU.json",
    "./starter-packs/starter_US.json",
    "./vendor/bootstrap/bootstrap.bundle.min.js",
    "./vendor/bootstrap/bootstrap.min.css"
];

self.addEventListener('install', (event) => {
    event.waitUntil(
        caches.open(CACHE).then(cache => cache.addAll(PRECACHE.map(u => new Request(u, { cache: 'reload' }))))
    );
});

self.addEventListener('activate', (event) => {
    event.waitUntil((async () => {
        const keys = await caches.keys();
        await Promise.all(keys.filter(k => k.startsWith('solidcutlist-') && k !== CACHE).map(k => caches.delete(k)));
        await self.clients.claim();
    })());
});

self.addEventListener('message', (event) => {
    if (event.data === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
    const req = event.request;
    if (req.method !== 'GET') return;
    const url = new URL(req.url);
    if (url.origin !== self.location.origin) return; // e.g. Google APIs: always network

    event.respondWith((async () => {
        const cache = await caches.open(CACHE);
        // App pages: the cached app shell (works offline, also for ?query links)
        if (req.mode === 'navigate') {
            return (await cache.match('./index.html')) || (await cache.match('./')) || fetch(req);
        }
        const hit = await cache.match(req, { ignoreSearch: true });
        if (hit) return hit;
        try {
            return await fetch(req);
        } catch (e) {
            return new Response('', { status: 504, statusText: 'Offline' });
        }
    })());
});
